<?php/** * Automated System Test Suite * Mobile Shop Management System */$testResults = [];
$failures = 0;
function runTest($testName, $callback)  {
        global $testResults, $failures;
        try  {
                $result = $callback();
                if ($result === true)  {
                        $testResults[] = ['status' => 'PASS', 'name' => $testName, 'error' => null];
        }
         else  {
                        $failures++;
                        $testResults[] = ['status' => 'FAIL', 'name' => $testName, 'error' => 'Assertion returned false'];
        }
    }
     catch (Throwable $e)  {
                $failures++;
                $testResults[] = ['status' => 'FAIL', 'name' => $testName, 'error' => $e->getMessage()];
    }
}
echo "=======================================================\n";
echo "  MOBILE SHOP MANAGEMENT SYSTEM - TEST SUITE\n";
echo "=======================================================\n\n";
// 1. Test Config HelpersrunTest('Config: URL Helper function exists and formats properly', function() {    require_once __DIR__ . '/../config/config.php';    $u = url('customer/mobiles.php');    return str_contains($u, 'customer/mobiles.php');});runTest('Config: FormatPrice produces correct currency formatting', function() {    $priceStr = formatPrice(35999);    return str_contains($priceStr, '35,999.00') && str_contains($priceStr, CURRENCY_SYMBOL);});runTest('Config: Sanitize escapes XSS characters', function() {    $raw = '<script>alert("test");</script>';    $clean = sanitize($raw);    return !str_contains($clean, '<script>') && str_contains($clean, '&lt;script&gt;');});runTest('Config: Flash message setter and getter work properly', function() {    setFlash('test_key', 'Hello Test', 'success');    $msg = getFlash('test_key');    $secondGet = getFlash('test_key');    return ($msg['message'] === 'Hello Test' && $msg['type'] === 'success' && $secondGet === null);});// 2. Test Auth HelpersrunTest('Auth: User login, session storage, and role checking', function() {    require_once __DIR__ . '/../includes/auth.php';    // Simulate admin login    $adminUser = ['id' => 1, 'name' => 'Admin User', 'email' => 'admin@test.com', 'role' => 'admin'];    loginUser($adminUser);    $logged = isLoggedIn();    $adminCheck = isAdmin();    $custCheck = isCustomer();    $curr = currentUser();    if (!$logged || !$adminCheck || $custCheck || $curr['name'] !== 'Admin User') {        return false;    }    // Simulate customer login    $custUser = ['id' => 2, 'name' => 'Customer User', 'email' => 'cust@test.com', 'role' => 'customer'];    loginUser($custUser);    $custCheck2 = isCustomer();    $adminCheck2 = isAdmin();    if (!$custCheck2 || $adminCheck2) {        return false;    }    // Logout    logoutUser();    return !isLoggedIn();});// 3. Test Password Hashing and Demo PasswordsrunTest('Security: Password hashing and verification for demo users', function() {    $passwords = [        'admin123'  => '$2y$10$.oL9GX2.nUmVfQh6VXA9f.VkS.n5fybZtGtKDcuA7pNExAxZwIaYy',        'aditya123' => '$2y$10$r8/1wtYz1qnpaxwdLEFoU.s6RFu2My9RXY4M13/Ylbcd.4o.e/YwK',        'sneha123'  => '$2y$10$Qm.XImmMqIXhzBE0yDrnlu8lD1wxguW1iPeXAAiFIzxnG572RT5eq',        'rohan123'  => '$2y$10$Ew6aDEZ8dYojpdtp3okS0.eXbWPF0Jeq1FxnFLBMK1GnpBSAZs4Bu',        'neha123'   => '$2y$10$8DcFPDQOEKQdFtXh5Qwa5.KFTWxPxx4qUmrmYb.8bnI9gMDKN3WAq',    ];    foreach ($passwords as $plain => $hash) {        if (!password_verify($plain, $hash)) {            throw new Exception("Password verification failed for '{$plain}'");        }    }    return true;});// 4. Test SQL Schema CompletenessrunTest('Database: SQL schema file exists and defines all recommended tables', function() {    $sqlFile = __DIR__ . '/../database/database.sql';    if (!file_exists($sqlFile)) {        throw new Exception("database/database.sql file not found!");    }    $content = file_get_contents($sqlFile);    $requiredTables = ['users', 'brands', 'mobiles', 'customers', 'sales', 'sale_items'];    foreach ($requiredTables as $tbl) {        if (!str_contains($content, "CREATE TABLE `{$tbl}`")) {            throw new Exception("Missing table creation for `{$tbl}` in database.sql");        }    }    // Check foreign keys    if (!str_contains($content, 'FOREIGN KEY (`brand_id`)') ||        !str_contains($content, 'FOREIGN KEY (`customer_id`)') ||        !str_contains($content, 'FOREIGN KEY (`sale_id`)') ||        !str_contains($content, 'FOREIGN KEY (`mobile_id`)')) {        throw new Exception("Missing foreign key relationships in database.sql");    }    return true;});// 5. Test Stock Reduction & Insufficient Stock Prevention LogicrunTest('Inventory & Sales: Stock reduction and insufficient stock verification', function() {    $mockMobile = [        'id' => 1,        'name' => 'Samsung Galaxy M35 5G',        'price' => 16999.00,        'stock' => 5    ];    // Case A: Valid purchase (quantity 2)    $qty = 2;    if ($mockMobile['stock'] < $qty) {        throw new Exception("Unexpected stock failure for valid purchase");    }    $totalAmount = $mockMobile['price'] * $qty;    $remainingStock = $mockMobile['stock'] - $qty;    if ($totalAmount !== 33998.00 || $remainingStock !== 3) {        throw new Exception("Calculation error in valid purchase");    }    // Case B: Insufficient stock attempt (quantity 6 when 5 available)    $excessQty = 6;    $insufficientCaught = false;    if ($mockMobile['stock'] < $excessQty) {        $insufficientCaught = true;    }    if (!$insufficientCaught) {        throw new Exception("Failed to detect insufficient stock condition!");    }    return true;});// 6. Test Demo Images Presence and QualityrunTest('Assets: All 20 realistic product images exist with valid dimensions and high quality', function() {    $images = [        'default_mobile.png',        'samsung_galaxy_m35.png',        'samsung_galaxy_a35.png',        'samsung_s24_ultra.png',        'oneplus_nord_ce4.png',        'oneplus_nord_4.png',        'oneplus_12r.png',        'redmi_note_13_pro.png',        'redmi_note_14.png',        'xiaomi_14_civi.png',        'realme_p1_5g.png',        'realme_narzo_70_pro.png',        'realme_12_pro_plus.png',        'vivo_t3_5g.png',        'vivo_v30.png',        'oppo_f27_5g.png',        'oppo_reno_12_pro.png',        'motorola_edge_50_fusion.png',        'motorola_g85_5g.png',        'iqoo_z9_5g.png',        'nothing_phone_2a.png'    ];    $imgDir = __DIR__ . '/../assets/images/';    foreach ($images as $img) {        $filePath = $imgDir . $img;        if (!file_exists($filePath)) {            throw new Exception("Missing image file: assets/images/{$img}");        }        $fileSize = filesize($filePath);        if ($fileSize < 1000) {            throw new Exception("Image file too small or corrupt: assets/images/{$img} ({$fileSize} bytes)");        }        if (function_exists('imagecreatefrompng')) {            $im = @imagecreatefrompng($filePath);            if (!$im) {                throw new Exception("Invalid PNG image format: assets/images/{$img}");            }            $w = imagesx($im);            $h = imagesy($im);            imagedestroy($im);        } else {            $sz = @getimagesize($filePath);            if (!$sz) {                throw new Exception("Invalid PNG image format: assets/images/{$img}");            }            $w = $sz[0];            $h = $sz[1];        }        if ($w < 100 || $h < 100) {            throw new Exception("Image dimensions too small for {$img}: {$w}x{$h}px");        }    }    return true;});// Display resultsforeach ($testResults as $t) {    if ($t['status'] === 'PASS') {        echo "[ PASS ] " . $t['name'] . "\n";    } else {        echo "[ FAIL ] " . $t['name'] . " -> " . $t['error'] . "\n";    }}echo "\n-------------------------------------------------------\n";echo "Total Tests: " . count($testResults) . " | Passed: " . (count($testResults) - $failures) . " | Failed: " . $failures . "\n";echo "=======================================================\n";exit($failures === 0 ? 0 : 1);
